+      }
+
+      .intro {
+        margin: 0 0 1.5rem;
+        color: var(--muted);
+      }
+
+      form {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .form-field {
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 1rem;
+        background: rgba(255, 255, 255, 0.02);
+      }
+
+      .checkbox-row {
+        display: flex;
+        gap: 0.75rem;
+        align-items: flex-start;
+      }
+
+      input[type="checkbox"] {
+        width: 1.125rem;
+        height: 1.125rem;
+        margin: 0.175rem 0 0;
+        accent-color: var(--accent);
+        flex: none;
+      }
+
+      label {
+        display: block;
+        font-weight: 600;
+        color: var(--text);
+        cursor: pointer;
+      }
+
+      .required {
+        color: var(--accent-strong);
+      }
+
+      .helper {
+        margin: 0.35rem 0 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      button {
+        appearance: none;
+        border: 1px solid var(--border-strong);
+        border-radius: 0.9rem;
+        padding: 0.875rem 1rem;
+        background: linear-gradient(180deg, #20315a 0%, #172547 100%);
+        color: var(--text);
+        font: inherit;
+        font-weight: 700;
+        cursor: pointer;
+        transition:
+          transform 0.15s ease,
+          border-color 0.15s ease,
+          background 0.15s ease;
+      }
+
+      button:hover {
+        border-color: var(--accent);
+        transform: translateY(-1px);
+      }
+
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      button:active {
+        transform: translateY(0);
+      }
+
+      .status {
+        min-height: 1.5rem;
+        color: var(--accent-strong);
+        font-weight: 600;
+      }
+
+      @media (max-width: 420px) {
+        .card {
+          padding: 1.25rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --bg: Canvas;
+          --bg-elevated: Canvas;
+          --bg-card: Canvas;
+          --border: ButtonBorder;
+          --border-strong: ButtonBorder;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --accent: ButtonText;
+          --accent-strong: ButtonText;
+          --focus: Highlight;
+        }
+
+        .card,
+        .form-field,
+        button {
+          forced-color-adjust: auto;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <div id="app"></div>
+
+    <script>
+      function App() {
+        return `
+          <main id="main-content">
+            <div class="shell">
+              <section class="card" aria-labelledby="consent-title">
+                <h1 id="consent-title">Consent to Terms of Use</h1>
+                <p class="intro">Please review and confirm your agreement before continuing.</p>
+                <form id="consent-form" novalidate>
+                  <div class="form-field">
+                    <div class="checkbox-row">
+                      <input
+                        id="terms"
+                        name="terms"
+                        type="checkbox"
+                        required
+                        aria-describedby="terms-help"
+                      />
+                      <div>
+                        <label for="terms">
+                          I agree to the Terms of Use <span class="required">*</span>
+                        </label>
+                        <p class="helper" id="terms-help">
+                          Required to proceed.
+                        </p>
+                      </div>
+                    </div>
+                  </div>
+                  <button type="submit">Submit</button>
+                  <p class="status" id="form-status" aria-live="polite"></p>
+                </form>
+              </section>
+            </div>
+          </main>
+        `;
+      }
+
+      document.getElementById("app").innerHTML = App();
+
+      const form = document.getElementById("consent-form");
+      const checkbox = document.getElementById("terms");
+      const status = document.getElementById("form-status");
+
+      form.addEventListener("submit", (event) => {
+        if (!checkbox.checked) {
+          event.preventDefault();
+          checkbox.setCustomValidity("You must agree to the Terms of Use before continuing.");
+          checkbox.reportValidity();
+          status.textContent = "";
+          return;
+        }
+
+        checkbox.setCustomValidity("");
+        status.textContent = "Consent saved.";
+        event.preventDefault();
+      });
+
+      checkbox.addEventListener("change", () => {
+        checkbox.setCustomValidity("");
+      });
+    </script>
+  </body>
+</html>
*** End Patch
